"use client";

import type { CSSProperties, ReactNode } from "react";
import { Easing, interpolate, useCurrentFrame } from "remotion";

export type DynamicGridVariant = "light" | "dark";
export type DynamicGridDirection = "diagonal" | "horizontal" | "vertical";

export interface DynamicGridProps {
  /** Palette preset. Light: #FAFAFA/#E4E7EC. Dark: #0A0A0B/#26272B. */
  variant?: DynamicGridVariant;
  /** Grid cell size in pixels. */
  cellSize?: number;
  /** Pixels drifted per frame. Motion wraps at `cellSize`, so it loops seamlessly. */
  speed?: number;
  /** Direction the grid drifts. */
  direction?: DynamicGridDirection;
  /** Canvas color override. Defaults per variant. */
  background?: string;
  /** Grid line color override. Defaults per variant. */
  lineColor?: string;
  /** Radial mask that fades the grid out toward the edges. */
  edgeFade?: boolean;
  /** Pulse a single accent cell that drifts along with the grid. */
  accentPulse?: boolean;
  /** Accent cell / string-token color. */
  accentColor?: string;
  /** Column of the pulsing accent cell (in the drifting grid layer). */
  accentCol?: number;
  /** Row of the pulsing accent cell (in the drifting grid layer). */
  accentRow?: number;
  /** Full pulse cycle length in frames. */
  pulsePeriod?: number;
  /** Render the built-in developer-platform hero (badge, headline, code block). */
  showHero?: boolean;
  /** Small pill above the headline. Empty string hides it. */
  badge?: string;
  /** Hero headline. */
  title?: string;
  /** One-line supporting copy under the headline. */
  subtitle?: string;
  /** Filename shown in the code-block chrome. */
  codeTitle?: string;
  /** Code-block lines — array, or a single newline-separated string. */
  codeLines?: string[] | string;
  className?: string;
  /** Custom foreground content rendered over the grid. */
  children?: ReactNode;
}

const SANS_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const MONO_FAMILY =
  "'JetBrains Mono', var(--font-geist-mono), ui-monospace, SFMono-Regular, Menlo, monospace";

/** Per-variant snap-cn palette for the canvas, lines and hero content. */
export const GRID_PALETTES: Record<
  DynamicGridVariant,
  {
    background: string;
    lineColor: string;
    surface: string;
    border: string;
    text: string;
    muted: string;
    shadow: string;
  }
> = {
  light: {
    background: "#FAFAFA",
    lineColor: "#E4E7EC",
    surface: "#FFFFFF",
    border: "#E4E7EC",
    text: "#101828",
    muted: "#667085",
    shadow: "0 16px 40px rgba(16,24,40,0.08)",
  },
  dark: {
    background: "#0A0A0B",
    lineColor: "#26272B",
    surface: "#141417",
    border: "#26272B",
    text: "#FAFAFA",
    muted: "#A1A1AA",
    shadow: "0 24px 60px rgba(0,0,0,0.45)",
  },
};

/**
 * Pure drift schedule. Offset wraps at `cellSize` so the grid loops
 * seamlessly; the returned translation is applied to the grid layer.
 */
export function gridOffset(
  frame: number,
  speed: number,
  cellSize: number,
  direction: DynamicGridDirection,
): { tx: number; ty: number } {
  const offset = cellSize > 0 ? (frame * speed) % cellSize : 0;
  if (direction === "horizontal") return { tx: offset, ty: 0 };
  if (direction === "vertical") return { tx: 0, ty: offset };
  return { tx: offset, ty: offset };
}

/**
 * Smooth cosine pulse for the accent cell: starts at `min`, peaks at `max`
 * halfway through `periodFrames`, and returns to `min` — loops seamlessly.
 */
export function pulseOpacity(
  frame: number,
  periodFrames: number,
  min = 0.05,
  max = 0.22,
): number {
  if (periodFrames <= 0) return min;
  const phase = 0.5 - 0.5 * Math.cos((frame / periodFrames) * Math.PI * 2);
  return min + (max - min) * phase;
}

/** Accepts an array or a newline-separated string; trims trailing blank lines. */
export function normalizeCodeLines(codeLines: string[] | string): string[] {
  const lines = Array.isArray(codeLines)
    ? [...codeLines]
    : codeLines.split("\n");
  while (lines.length > 0 && lines[lines.length - 1].trim() === "") lines.pop();
  return lines;
}

export type CodeSegmentKind = "code" | "string" | "comment";

export interface CodeSegment {
  text: string;
  kind: CodeSegmentKind;
}

/**
 * Minimal deterministic tokenizer for the demo code block:
 * `// …` lines become a single comment segment, double-quoted
 * spans become string segments, everything else is plain code.
 */
export function splitCodeSegments(line: string): CodeSegment[] {
  if (line.trim().startsWith("//")) {
    return [{ text: line, kind: "comment" }];
  }
  const segments: CodeSegment[] = [];
  for (const part of line.split(/("[^"]*")/)) {
    if (part.length === 0) continue;
    segments.push({
      text: part,
      kind: part.startsWith('"') ? "string" : "code",
    });
  }
  return segments;
}

const DEFAULT_CODE_LINES = [
  'import { Acme } from "@acme/sdk";',
  "",
  'const app = new Acme({ region: "iad" });',
  "",
  'const url = await app.deploy("./web");',
];

export function DynamicGrid({
  variant = "light",
  cellSize = 48,
  speed = 0.25,
  direction = "diagonal",
  background,
  lineColor,
  edgeFade = false,
  accentPulse = false,
  accentColor = "#266DF0",
  accentCol = 5,
  accentRow = 3,
  pulsePeriod = 90,
  showHero = false,
  badge = "Acme Developer Platform",
  title = "Ship on the Acme platform",
  subtitle = "One SDK, every runtime — deploy your app in seconds.",
  codeTitle = "deploy.ts",
  codeLines = DEFAULT_CODE_LINES,
  className,
  children,
}: DynamicGridProps) {
  const frame = useCurrentFrame();

  const palette = GRID_PALETTES[variant] ?? GRID_PALETTES.light;
  const canvas = background ?? palette.background;
  const line = lineColor ?? palette.lineColor;

  const { tx, ty } = gridOffset(frame, speed, cellSize, direction);

  const maskStyle: CSSProperties = edgeFade
    ? {
        WebkitMaskImage:
          "radial-gradient(ellipse 78% 78% at 50% 50%, black 52%, transparent 100%)",
        maskImage:
          "radial-gradient(ellipse 78% 78% at 50% 50%, black 52%, transparent 100%)",
      }
    : {};

  const lines = normalizeCodeLines(codeLines);
  const segmentColor: Record<CodeSegmentKind, string> = {
    code: palette.text,
    string: accentColor,
    comment: palette.muted,
  };

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background: canvas,
        overflow: "hidden",
        fontFamily: SANS_FAMILY,
      }}
    >
      {/* Screen-fixed mask wrapper so the edge fade stays put while the grid drifts. */}
      <div style={{ position: "absolute", inset: 0, ...maskStyle }}>
        <div
          style={{
            position: "absolute",
            inset: `-${cellSize}px`,
            backgroundImage: `
              linear-gradient(to right, ${line} 1px, transparent 1px),
              linear-gradient(to bottom, ${line} 1px, transparent 1px)
            `,
            backgroundSize: `${cellSize}px ${cellSize}px`,
            translate: `${tx}px ${ty}px`,
            willChange: "transform",
          }}
        >
          {accentPulse ? (
            <div
              style={{
                position: "absolute",
                left: accentCol * cellSize + 1,
                top: accentRow * cellSize + 1,
                width: cellSize - 1,
                height: cellSize - 1,
                backgroundColor: accentColor,
                opacity: pulseOpacity(frame, pulsePeriod),
              }}
            />
          ) : null}
        </div>
      </div>

      {showHero ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            gap: 0,
          }}
        >
          {badge ? (
            <div
              style={{
                padding: "5px 12px",
                borderRadius: 999,
                backgroundColor: palette.surface,
                border: `1px solid ${palette.border}`,
                color: palette.muted,
                fontSize: 12,
                fontWeight: 600,
                letterSpacing: "0.02em",
                opacity: interpolate(frame, [0, 12], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
                translate: interpolate(frame, [0, 14], ["0px 8px", "0px 0px"], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.out(Easing.cubic),
                }),
              }}
            >
              {badge}
            </div>
          ) : null}

          <div
            style={{
              marginTop: 18,
              fontSize: 54,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              lineHeight: 1.1,
              color: palette.text,
              textAlign: "center",
              maxWidth: 760,
              opacity: interpolate(frame, [4, 18], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              translate: interpolate(frame, [4, 20], ["0px 12px", "0px 0px"], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.cubic),
              }),
            }}
          >
            {title}
          </div>

          <div
            style={{
              marginTop: 14,
              fontSize: 19,
              lineHeight: 1.5,
              color: palette.muted,
              textAlign: "center",
              maxWidth: 620,
              opacity: interpolate(frame, [8, 22], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              translate: interpolate(frame, [8, 24], ["0px 10px", "0px 0px"], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.cubic),
              }),
            }}
          >
            {subtitle}
          </div>

          {/* Code block floating over the grid: eased entrance + slow bob. */}
          <div
            style={{
              marginTop: 32,
              width: 560,
              borderRadius: 10,
              backgroundColor: palette.surface,
              border: `1px solid ${palette.border}`,
              boxShadow: palette.shadow,
              overflow: "hidden",
              opacity: interpolate(frame, [12, 28], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              translate: `0px ${
                interpolate(frame, [12, 30], [18, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.out(Easing.cubic),
                }) +
                Math.sin((frame / 120) * Math.PI * 2) * 3
              }px`,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                padding: "10px 14px",
                borderBottom: `1px solid ${palette.border}`,
              }}
            >
              <span
                style={{
                  width: 9,
                  height: 9,
                  borderRadius: 999,
                  backgroundColor: palette.border,
                }}
              />
              <span
                style={{
                  width: 9,
                  height: 9,
                  borderRadius: 999,
                  backgroundColor: palette.border,
                }}
              />
              <span
                style={{
                  width: 9,
                  height: 9,
                  borderRadius: 999,
                  backgroundColor: palette.border,
                }}
              />
              <span
                style={{
                  marginLeft: 6,
                  fontSize: 12,
                  color: palette.muted,
                  fontFamily: MONO_FAMILY,
                }}
              >
                {codeTitle}
              </span>
            </div>
            <div style={{ padding: "16px 18px" }}>
              {lines.map((codeLine, i) => (
                <div
                  // biome-ignore lint/suspicious/noArrayIndexKey: static frame-driven list
                  key={i}
                  style={{
                    fontFamily: MONO_FAMILY,
                    fontSize: 15,
                    lineHeight: 1.7,
                    whiteSpace: "pre",
                    minHeight: "1.7em",
                    opacity: interpolate(
                      frame,
                      [24 + i * 4, 34 + i * 4],
                      [0, 1],
                      {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                      },
                    ),
                  }}
                >
                  {splitCodeSegments(codeLine).map((segment, j) => (
                    <span
                      // biome-ignore lint/suspicious/noArrayIndexKey: static segment list
                      key={j}
                      style={{ color: segmentColor[segment.kind] }}
                    >
                      {segment.text}
                    </span>
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : null}

      {children}
    </div>
  );
}
